"use client";
// METAFORGE-BGREMOVER v1 - Background Remover workspace. All processing runs in the browser.
// Generated by install-background-remover.ps1. Safe to edit; re-running the installer backs this file up first.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ChangeEvent, CSSProperties, DragEvent as ReactDragEvent } from "react";
import styles from "./BackgroundRemover.module.css";
import {
  ACCEPT_ATTRIBUTE,
  LIMITS,
  describeError,
  formatBytes,
  formatDuration,
  inspectPng,
  makeId,
  measureAlpha,
  outputFileName,
  uniqueName,
  validateImageFile,
} from "./bgr-utils";
import type { AlphaStats } from "./bgr-utils";
import { DEFAULT_MODEL, MODEL_OPTIONS, removeBackgroundFromFile } from "./bgr-engine";
import type { ModelId } from "./bgr-engine";

type Status = "ready" | "queued" | "processing" | "done" | "failed";
type PreviewMode = "checker" | "white" | "black" | "custom";

interface ResultInfo {
  blob: Blob;
  url: string;
  bytes: number;
  width: number;
  height: number;
  durationMs: number;
  transparentPct: number;
  partialPct: number;
  warning?: string;
  model: ModelId;
}

interface Item {
  id: string;
  file: File;
  key: string;
  name: string;
  bytes: number;
  width: number;
  height: number;
  originalUrl: string;
  status: Status;
  stage?: string;
  error?: string;
  result?: ResultInfo;
}

interface Notice {
  id: number;
  kind: "error" | "info";
  text: string;
}

const STATUS_LABEL: Record<Status, string> = {
  ready: "Ready",
  queued: "Queued",
  processing: "Processing",
  done: "Done",
  failed: "Failed",
};

const PREVIEW_OPTIONS: { id: PreviewMode; label: string }[] = [
  { id: "checker", label: "Checkerboard" },
  { id: "white", label: "White" },
  { id: "black", label: "Black" },
  { id: "custom", label: "Custom" },
];

const FULLY_TRANSPARENT_PCT = 99.99;
const NOTHING_REMOVED_PCT = 0.05;

function revokeAll(ref: { current: Item[] }) {
  for (const item of ref.current) {
    URL.revokeObjectURL(item.originalUrl);
    if (item.result) URL.revokeObjectURL(item.result.url);
  }
}

function triggerDownload(url: string, filename: string) {
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

function modelLabel(id: ModelId): string {
  return MODEL_OPTIONS.find((m) => m.id === id)?.label ?? id;
}

/* ------------------------------------------------------------------ */
/* Before / after inspector                                            */
/* ------------------------------------------------------------------ */

interface InspectProps {
  item: Item;
  previewClass: string;
  previewStyle: CSSProperties | undefined;
  onClose: () => void;
}

const ZOOM_LEVELS: { value: number; label: string }[] = [
  { value: 0, label: "Fit" },
  { value: 1, label: "100%" },
  { value: 2, label: "200%" },
  { value: 4, label: "400%" },
  { value: 8, label: "800%" },
];

function InspectModal({ item, previewClass, previewStyle, onClose }: InspectProps) {
  const [zoom, setZoom] = useState<number>(0);
  const [split, setSplit] = useState<number>(50);

  useEffect(() => {
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = previousOverflow;
    };
  }, [onClose]);

  const result = item.result;
  if (!result) return null;

  const stageStyle: CSSProperties = {
    width: zoom === 0 ? "100%" : result.width * zoom,
    aspectRatio: `${result.width} / ${result.height}`,
    imageRendering: zoom >= 2 ? "pixelated" : "auto",
  };

  return (
    <div className={styles.modalBackdrop} onClick={onClose}>
      <div
        className={styles.modal}
        role="dialog"
        aria-modal="true"
        aria-label={`Compare original and result for ${item.name}`}
        onClick={(event) => event.stopPropagation()}
      >
        <div className={styles.modalHeader}>
          <h2 className={styles.modalTitle} title={item.name}>
            {item.name}
          </h2>
          <button type="button" className={styles.btn} onClick={onClose}>
            Close
          </button>
        </div>

        <div className={styles.modalToolbar}>
          <div className={styles.seg} role="group" aria-label="Zoom level">
            {ZOOM_LEVELS.map((level) => (
              <button
                key={level.value}
                type="button"
                className={`${styles.segBtn} ${zoom === level.value ? styles.segBtnActive : ""}`}
                aria-pressed={zoom === level.value}
                onClick={() => setZoom(level.value)}
              >
                {level.label}
              </button>
            ))}
          </div>
          <label className={styles.sliderLabel}>
            <span>Original</span>
            <input
              type="range"
              min={0}
              max={100}
              value={split}
              onChange={(event) => setSplit(Number(event.target.value))}
              aria-label="Move the divider between original and result"
            />
            <span>Result</span>
          </label>
        </div>

        <div className={styles.modalViewport}>
          <div className={styles.stage} style={stageStyle}>
            <div
              className={styles.layer}
              role="img"
              aria-label="Original image"
              style={{ backgroundImage: `url("${item.originalUrl}")` }}
            />
            <div
              className={`${styles.layer} ${previewClass}`}
              style={{ ...previewStyle, clipPath: `inset(0 0 0 ${split}%)` }}
            >
              <div
                className={styles.layer}
                role="img"
                aria-label="Transparent result"
                style={{ backgroundImage: `url("${result.url}")` }}
              />
            </div>
            <div className={styles.divider} style={{ left: `${split}%` }} />
          </div>
        </div>

        <p className={styles.modalNote}>
          Zoom only changes how the image is displayed. It does not upscale or enhance the exported PNG, which is{" "}
          {result.width} &times; {result.height} px.
        </p>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* One result row                                                      */
/* ------------------------------------------------------------------ */

interface RowProps {
  item: Item;
  selected: boolean;
  queuePosition: number;
  previewClass: string;
  previewStyle: CSSProperties | undefined;
  onSelect: (id: string) => void;
  onRun: (id: string) => void;
  onCancel: (id: string) => void;
  onRemove: (id: string) => void;
  onDownload: (id: string) => void;
  onInspect: (id: string) => void;
}

function ItemRow(props: RowProps) {
  const { item, selected, queuePosition, previewClass, previewStyle } = props;
  const result = item.result;
  const badgeClass =
    item.status === "done"
      ? styles.badgeDone
      : item.status === "failed"
        ? styles.badgeFailed
        : item.status === "processing"
          ? styles.badgeProcessing
          : item.status === "queued"
            ? styles.badgeQueued
            : styles.badgeReady;

  return (
    <article
      className={`${styles.row} ${selected ? styles.rowSelected : ""}`}
      onClick={() => props.onSelect(item.id)}
      aria-label={`${item.name}: ${STATUS_LABEL[item.status]}`}
    >
      <div className={styles.rowHeader}>
        <div className={styles.rowTitleWrap}>
          <h3 className={styles.rowTitle}>
            <button
              type="button"
              className={styles.titleBtn}
              title={item.name}
              aria-pressed={selected}
              onClick={() => props.onSelect(item.id)}
            >
              {item.name}
            </button>
          </h3>
          <span className={`${styles.badge} ${badgeClass}`}>{STATUS_LABEL[item.status]}</span>
        </div>

        <div className={styles.rowActions} onClick={(event) => event.stopPropagation()}>
          {item.status === "ready" && (
            <button type="button" className={`${styles.btn} ${styles.btnPrimary}`} onClick={() => props.onRun(item.id)}>
              Remove background
            </button>
          )}
          {item.status === "queued" && (
            <button type="button" className={styles.btn} onClick={() => props.onCancel(item.id)}>
              Cancel
            </button>
          )}
          {item.status === "failed" && (
            <button type="button" className={`${styles.btn} ${styles.btnPrimary}`} onClick={() => props.onRun(item.id)}>
              Retry
            </button>
          )}
          {item.status === "done" && result && (
            <>
              <button
                type="button"
                className={`${styles.btn} ${styles.btnPrimary}`}
                onClick={() => props.onDownload(item.id)}
              >
                Download PNG
              </button>
              <button type="button" className={styles.btn} onClick={() => props.onInspect(item.id)}>
                Compare &amp; inspect
              </button>
              <button type="button" className={styles.btn} onClick={() => props.onRun(item.id)}>
                Reprocess
              </button>
            </>
          )}
          <button
            type="button"
            className={styles.btn}
            disabled={item.status === "processing"}
            title={item.status === "processing" ? "An image that is already processing cannot be stopped." : undefined}
            onClick={() => props.onRemove(item.id)}
          >
            Remove
          </button>
        </div>
      </div>

      <p className={styles.rowMeta}>
        Original: {item.width} &times; {item.height} px &middot; {formatBytes(item.bytes)}
        {result && (
          <>
            {" "}
            &nbsp;|&nbsp; Output: {result.width} &times; {result.height} px &middot; PNG {formatBytes(result.bytes)}{" "}
            &middot; {formatDuration(result.durationMs)} &middot; {modelLabel(result.model)} model &middot; alpha channel
            verified, {(result.transparentPct + result.partialPct).toFixed(1)}% of sampled pixels transparent or
            semi-transparent
          </>
        )}
      </p>
      {result?.warning && <p className={styles.warn}>{result.warning}</p>}

      <div className={styles.panels}>
        <div className={styles.panelBox}>
          <div className={styles.panelLabel}>Original</div>
          <div className={styles.panelBody}>
            <div
              className={styles.imgLayer}
              role="img"
              aria-label={`Original image ${item.name}`}
              style={{ backgroundImage: `url("${item.originalUrl}")` }}
            />
          </div>
        </div>

        <div className={styles.panelBox}>
          <div className={styles.panelLabel}>Transparent PNG</div>
          <div
            className={`${styles.panelBody} ${result ? previewClass : ""}`}
            style={result ? previewStyle : undefined}
          >
            {result ? (
              <div
                className={styles.imgLayer}
                role="img"
                aria-label={`Transparent result for ${item.name}`}
                style={{ backgroundImage: `url("${result.url}")` }}
              />
            ) : (
              <div className={styles.placeholder}>
                {item.status === "ready" && <p>Not processed yet.</p>}
                {item.status === "queued" && <p>Waiting in the queue (position {queuePosition}).</p>}
                {item.status === "processing" && (
                  <>
                    <p>{item.stage ?? "Processing"}</p>
                    <p className={styles.dim}>
                      The first image also downloads the model files, so it takes longer. Images are processed one at
                      a time.
                    </p>
                  </>
                )}
                {item.status === "failed" && (
                  <p className={styles.errorText} role="alert">
                    {item.error ?? "Processing failed."}
                  </p>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

/* ------------------------------------------------------------------ */
/* Workspace                                                           */
/* ------------------------------------------------------------------ */

export default function BackgroundRemoverWorkspace() {
  const [items, setItems] = useState<Item[]>([]);
  const itemsRef = useRef<Item[]>([]);
  const runningRef = useRef(false);
  const addingRef = useRef(false);
  const modelRef = useRef<ModelId>(DEFAULT_MODEL);
  const noticeSeq = useRef(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [model, setModel] = useState<ModelId>(DEFAULT_MODEL);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [inspectId, setInspectId] = useState<string | null>(null);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [validating, setValidating] = useState(false);
  const [zipping, setZipping] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [previewMode, setPreviewMode] = useState<PreviewMode>("checker");
  const [customColor, setCustomColor] = useState("#3a86ff");

  // Single source of truth is itemsRef (readable inside async work); state mirrors it for rendering.
  const commit = useCallback((updater: (prev: Item[]) => Item[]) => {
    const next = updater(itemsRef.current);
    itemsRef.current = next;
    setItems(next);
  }, []);

  const pushNotice = useCallback((kind: Notice["kind"], text: string) => {
    noticeSeq.current += 1;
    const id = noticeSeq.current;
    setNotices((prev) => [...prev, { id, kind, text }].slice(-6));
  }, []);

  // Release every object URL when the page is left.
  useEffect(() => {
    return () => revokeAll(itemsRef);
  }, []);

  /* ----- adding files ----- */

  const addFiles = useCallback(
    async (fileList: FileList | File[]) => {
      const files = Array.from(fileList);
      if (files.length === 0) return;
      if (addingRef.current) {
        pushNotice("info", "Still checking the previous files. Please try again in a moment.");
        return;
      }
      addingRef.current = true;
      setValidating(true);
      const problems: string[] = [];
      const accepted: Item[] = [];
      try {
        for (const file of files) {
          if (itemsRef.current.length + accepted.length >= LIMITS.maxFiles) {
            problems.push(
              `${file.name}: not added. The limit is ${LIMITS.maxFiles} images at a time; remove some images first.`,
            );
            continue;
          }
          const key = `${file.name}|${file.size}|${file.lastModified}`;
          if (itemsRef.current.some((i) => i.key === key) || accepted.some((i) => i.key === key)) {
            problems.push(`${file.name}: already in the list.`);
            continue;
          }
          const check = await validateImageFile(file);
          if (!check.ok) {
            problems.push(`${file.name}: ${check.reason}`);
            continue;
          }
          accepted.push({
            id: makeId(),
            file,
            key,
            name: file.name,
            bytes: file.size,
            width: check.width,
            height: check.height,
            originalUrl: URL.createObjectURL(file),
            status: "ready",
          });
        }
      } finally {
        addingRef.current = false;
        setValidating(false);
      }
      if (accepted.length > 0) {
        commit((prev) => [...prev, ...accepted]);
        setSelectedId((current) => current ?? accepted[0].id);
      }
      for (const problem of problems) pushNotice("error", problem);
    },
    [commit, pushNotice],
  );

  /* ----- processing queue (one image at a time) ----- */

  const processItem = useCallback(
    async (id: string) => {
      const start = itemsRef.current.find((i) => i.id === id);
      if (!start || start.status !== "queued") return;
      const modelUsed = modelRef.current;
      commit((prev) =>
        prev.map((i) => (i.id === id ? { ...i, status: "processing", stage: "Starting", error: undefined } : i)),
      );
      const t0 = performance.now();
      try {
        const blob = await removeBackgroundFromFile(start.file, modelUsed, (stage) => {
          commit((prev) => prev.map((i) => (i.id === id && i.status === "processing" ? { ...i, stage } : i)));
        });
        const durationMs = performance.now() - t0;
        if (!itemsRef.current.some((i) => i.id === id)) return;

        const png = await inspectPng(blob);
        if (!png.validSignature) throw new Error("The engine did not return a valid PNG file.");
        if (!png.hasAlphaChannel) {
          throw new Error("The output PNG has no alpha channel, so it cannot be transparent.");
        }
        let alpha: AlphaStats;
        try {
          alpha = await measureAlpha(blob);
        } catch {
          throw new Error(
            "The output PNG could not be decoded to verify its transparency (the browser may be low on memory).",
          );
        }
        if (alpha.transparentPct >= FULLY_TRANSPARENT_PCT) {
          throw new Error(
            "The engine returned a fully transparent image, so none of the foreground was kept. Try a different model.",
          );
        }
        const warning =
          alpha.transparentPct + alpha.partialPct < NOTHING_REMOVED_PCT
            ? "No background pixels were made transparent. The model may have treated the whole image as foreground."
            : undefined;
        const url = URL.createObjectURL(blob);
        commit((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: "done",
                  stage: undefined,
                  error: undefined,
                  result: {
                    blob,
                    url,
                    bytes: blob.size,
                    width: png.width,
                    height: png.height,
                    durationMs,
                    transparentPct: alpha.transparentPct,
                    partialPct: alpha.partialPct,
                    warning,
                    model: modelUsed,
                  },
                }
              : i,
          ),
        );
      } catch (err) {
        const message = describeError(err);
        commit((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: "failed", stage: undefined, error: message } : i)),
        );
      }
    },
    [commit],
  );

  const pump = useCallback(async () => {
    if (runningRef.current) return;
    runningRef.current = true;
    try {
      for (;;) {
        const next = itemsRef.current.find((i) => i.status === "queued");
        if (!next) break;
        await processItem(next.id);
      }
    } finally {
      runningRef.current = false;
    }
  }, [processItem]);

  const enqueue = useCallback(
    (ids: string[]) => {
      let queued = 0;
      commit((prev) =>
        prev.map((item) => {
          if (!ids.includes(item.id)) return item;
          // Already waiting or running: never submit the same image twice.
          if (item.status === "queued" || item.status === "processing") return item;
          if (item.result) URL.revokeObjectURL(item.result.url);
          queued += 1;
          return { ...item, status: "queued", error: undefined, stage: undefined, result: undefined };
        }),
      );
      if (queued > 0) void pump();
    },
    [commit, pump],
  );

  const cancelQueued = useCallback(
    (ids?: string[]) => {
      commit((prev) =>
        prev.map((item) =>
          item.status === "queued" && (!ids || ids.includes(item.id)) ? { ...item, status: "ready" } : item,
        ),
      );
    },
    [commit],
  );

  /* ----- list management ----- */

  const removeItem = useCallback(
    (id: string) => {
      const item = itemsRef.current.find((i) => i.id === id);
      if (!item || item.status === "processing") return;
      if (
        item.status === "done" &&
        !window.confirm(`Remove "${item.name}" and its processed result? Download it first if you still need it.`)
      ) {
        return;
      }
      URL.revokeObjectURL(item.originalUrl);
      if (item.result) URL.revokeObjectURL(item.result.url);
      commit((prev) => prev.filter((i) => i.id !== id));
      setSelectedId((current) => (current === id ? null : current));
      setInspectId((current) => (current === id ? null : current));
    },
    [commit],
  );

  const clearCompleted = useCallback(() => {
    const done = itemsRef.current.filter((i) => i.status === "done");
    if (done.length === 0) return;
    if (!window.confirm(`Clear ${done.length} completed result(s)? Anything you have not downloaded will be lost.`)) {
      return;
    }
    for (const item of done) {
      URL.revokeObjectURL(item.originalUrl);
      if (item.result) URL.revokeObjectURL(item.result.url);
    }
    const doneIds = new Set(done.map((i) => i.id));
    commit((prev) => prev.filter((i) => !doneIds.has(i.id)));
    setSelectedId((current) => (current && doneIds.has(current) ? null : current));
    setInspectId(null);
  }, [commit]);

  /* ----- downloads ----- */

  const downloadOne = useCallback((id: string) => {
    const item = itemsRef.current.find((i) => i.id === id);
    if (!item || item.status !== "done" || !item.result) return;
    triggerDownload(item.result.url, outputFileName(item.name));
  }, []);

  const downloadAll = useCallback(async () => {
    const outputs = itemsRef.current.flatMap((i) =>
      i.status === "done" && i.result ? [{ name: i.name, blob: i.result.blob }] : [],
    );
    if (outputs.length === 0) return;
    setZipping(true);
    try {
      const mod = await import("jszip");
      const JSZip = mod.default;
      const zip = new JSZip();
      const used = new Set<string>();
      for (const output of outputs) {
        zip.file(uniqueName(outputFileName(output.name), used), output.blob);
      }
      // PNG is already compressed, so the archive stores files without recompressing them.
      const archive = await zip.generateAsync({ type: "blob", compression: "STORE" });
      const url = URL.createObjectURL(archive);
      const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
      triggerDownload(url, `background-removed-${stamp}.zip`);
      window.setTimeout(() => URL.revokeObjectURL(url), 30000);
    } catch (err) {
      pushNotice("error", `Could not create the ZIP file: ${describeError(err)}`);
    } finally {
      setZipping(false);
    }
  }, [pushNotice]);

  /* ----- derived state ----- */

  const counts = useMemo(() => {
    const c: Record<Status, number> = { ready: 0, queued: 0, processing: 0, done: 0, failed: 0 };
    for (const item of items) c[item.status] += 1;
    return c;
  }, [items]);

  const selected = items.find((i) => i.id === selectedId) ?? null;
  const canRunSelected =
    !!selected && (selected.status === "ready" || selected.status === "failed" || selected.status === "done");
  const inspected = items.find((i) => i.id === inspectId) ?? null;
  const queueOrder = items.filter((i) => i.status === "queued").map((i) => i.id);

  const previewClass = previewMode === "checker" ? styles.checker : "";
  const previewStyle: CSSProperties | undefined =
    previewMode === "white"
      ? { background: "#ffffff" }
      : previewMode === "black"
        ? { background: "#000000" }
        : previewMode === "custom"
          ? { background: customColor }
          : undefined;

  const runSelected = () => {
    if (!selected) return;
    if (
      selected.status === "done" &&
      !window.confirm("Reprocessing replaces the current result for this image. Continue?")
    ) {
      return;
    }
    enqueue([selected.id]);
  };

  const runAllEligible = () => {
    enqueue(itemsRef.current.filter((i) => i.status === "ready").map((i) => i.id));
  };

  const retryFailed = () => {
    enqueue(itemsRef.current.filter((i) => i.status === "failed").map((i) => i.id));
  };

  const runOne = (id: string) => {
    const item = itemsRef.current.find((i) => i.id === id);
    if (!item) return;
    if (item.status === "done" && !window.confirm("Reprocessing replaces the current result for this image. Continue?")) {
      return;
    }
    enqueue([id]);
  };

  const chooseModel = (id: ModelId) => {
    modelRef.current = id;
    setModel(id);
  };

  const openPicker = () => fileInputRef.current?.click();

  const onPick = (event: ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) void addFiles(files);
    event.target.value = "";
  };

  const onDrop = (event: ReactDragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragOver(false);
    void addFiles(event.dataTransfer.files);
  };

  const activeModel = MODEL_OPTIONS.find((m) => m.id === model);

  return (
    <section className={styles.root}>
      <header className={styles.pageHeader}>
        <h1 className={styles.pageTitle}>Background Remover</h1>
        <p className={styles.pageLead}>
          Remove image backgrounds and export transparent PNG files. Images are processed in your browser and are not
          uploaded to a server. The model files are downloaded once on first use and then cached by the browser.
        </p>
      </header>

      <div
        className={`${styles.dropzone} ${dragOver ? styles.dropzoneActive : ""}`}
        onDragOver={(event) => {
          event.preventDefault();
          setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <p className={styles.dropTitle}>Drag and drop images here</p>
        <p className={styles.dropHint}>
          JPG, JPEG, PNG or WEBP &middot; up to {formatBytes(LIMITS.maxFileBytes)} and{" "}
          {(LIMITS.maxPixels / 1000000).toFixed(0)} megapixels each &middot; up to {LIMITS.maxFiles} images at a time
        </p>
        <button
          type="button"
          className={`${styles.btn} ${styles.btnPrimary}`}
          onClick={openPicker}
          disabled={validating}
        >
          {validating ? "Checking files..." : "Browse files"}
        </button>
        <input
          ref={fileInputRef}
          type="file"
          accept={ACCEPT_ATTRIBUTE}
          multiple
          hidden
          onChange={onPick}
          aria-label="Choose images"
        />
      </div>

      {notices.length > 0 && (
        <div className={styles.notices}>
          {notices.map((notice) => (
            <div
              key={notice.id}
              className={`${styles.notice} ${notice.kind === "error" ? styles.noticeError : styles.noticeInfo}`}
              role={notice.kind === "error" ? "alert" : "status"}
            >
              <span>{notice.text}</span>
              <button
                type="button"
                className={styles.noticeClose}
                aria-label="Dismiss message"
                onClick={() => setNotices((prev) => prev.filter((n) => n.id !== notice.id))}
              >
                &times;
              </button>
            </div>
          ))}
        </div>
      )}

      <div className={styles.settings}>
        <div className={styles.settingGroup}>
          <div className={styles.settingLabel}>Model</div>
          <div className={styles.seg} role="group" aria-label="Processing model">
            {MODEL_OPTIONS.map((option) => (
              <button
                key={option.id}
                type="button"
                className={`${styles.segBtn} ${model === option.id ? styles.segBtnActive : ""}`}
                aria-pressed={model === option.id}
                onClick={() => chooseModel(option.id)}
              >
                {option.label}
              </button>
            ))}
          </div>
          <p className={styles.settingHint}>{activeModel?.hint}</p>
        </div>

        <div className={styles.settingGroup}>
          <div className={styles.settingLabel}>Preview background (preview only)</div>
          <div className={styles.seg} role="group" aria-label="Preview background">
            {PREVIEW_OPTIONS.map((option) => (
              <button
                key={option.id}
                type="button"
                className={`${styles.segBtn} ${previewMode === option.id ? styles.segBtnActive : ""}`}
                aria-pressed={previewMode === option.id}
                onClick={() => setPreviewMode(option.id)}
              >
                {option.label}
              </button>
            ))}
            {previewMode === "custom" && (
              <input
                type="color"
                className={styles.colorInput}
                value={customColor}
                onChange={(event) => setCustomColor(event.target.value)}
                aria-label="Custom preview background color"
              />
            )}
          </div>
          <p className={styles.settingHint}>
            This only changes what you see here. Downloaded files are always transparent PNG.
          </p>
        </div>

        <div className={styles.settingGroup}>
          <div className={styles.settingLabel}>Output</div>
          <p className={styles.settingHint}>
            Transparent PNG. The exact output size, file size and time are measured and shown on each result. Edge
            refinement, hair/fur detail and resolution are not adjustable with this engine, so no such controls are
            shown. Time includes the one-time model download for the first image.
          </p>
        </div>
      </div>

      <div className={styles.controls}>
        <div className={styles.controlButtons}>
          <button
            type="button"
            className={`${styles.btn} ${styles.btnPrimary}`}
            disabled={!canRunSelected}
            onClick={runSelected}
          >
            {selected?.status === "done" ? "Reprocess selected" : "Remove background (selected)"}
          </button>
          <button
            type="button"
            className={`${styles.btn} ${styles.btnPrimary}`}
            disabled={counts.ready === 0}
            onClick={runAllEligible}
          >
            Remove background from all ({counts.ready})
          </button>
          <button type="button" className={styles.btn} disabled={counts.queued === 0} onClick={() => cancelQueued()}>
            Cancel queued ({counts.queued})
          </button>
          <button type="button" className={styles.btn} disabled={counts.failed === 0} onClick={retryFailed}>
            Retry failed ({counts.failed})
          </button>
          <button type="button" className={styles.btn} disabled={counts.done === 0 || zipping} onClick={() => void downloadAll()}>
            {zipping ? "Creating ZIP..." : `Download all as ZIP (${counts.done})`}
          </button>
          <button type="button" className={styles.btn} disabled={counts.done === 0} onClick={clearCompleted}>
            Clear completed
          </button>
        </div>
        <ul className={styles.chips} aria-label="Status counts">
          <li className={styles.chip}>Ready: {counts.ready}</li>
          <li className={styles.chip}>Queued: {counts.queued}</li>
          <li className={styles.chip}>Processing: {counts.processing}</li>
          <li className={styles.chip}>Completed: {counts.done}</li>
          <li className={styles.chip}>Failed: {counts.failed}</li>
          <li className={styles.chip}>
            Total: {items.length} / {LIMITS.maxFiles}
          </li>
        </ul>
      </div>

      {items.length === 0 ? (
        <p className={styles.empty}>No images yet. Add some above to get started.</p>
      ) : (
        <div className={styles.rows}>
          {items.map((item) => (
            <ItemRow
              key={item.id}
              item={item}
              selected={item.id === selectedId}
              queuePosition={queueOrder.indexOf(item.id) + 1}
              previewClass={previewClass}
              previewStyle={previewStyle}
              onSelect={setSelectedId}
              onRun={runOne}
              onCancel={(id) => cancelQueued([id])}
              onRemove={removeItem}
              onDownload={downloadOne}
              onInspect={setInspectId}
            />
          ))}
        </div>
      )}

      {inspected && inspected.result && (
        <InspectModal
          item={inspected}
          previewClass={previewClass}
          previewStyle={previewStyle}
          onClose={() => setInspectId(null)}
        />
      )}
    </section>
  );
}